const clock = new THREE.Clock();
scene.background = new THREE.Color(0xdde6f0);
scene.fog = new THREE.FogExp2(0xdde6f0, 0.015);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff4e0, 1.45);
keyLight.position.set(40, 60, 30);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.1;
keyLight.shadow.camera.far = 200;
keyLight.shadow.camera.left = -60;
keyLight.shadow.camera.right = 60;
keyLight.shadow.camera.top = 60;
keyLight.shadow.camera.bottom = -60;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0x8fbfff, 0.65);
fillLight.position.set(-50, 40, -30);

const rimLight = new THREE.DirectionalLight(0xcceeff, 0.95);
rimLight.position.set(0, 30, -70);

const ambientLight = new THREE.AmbientLight(0x4a5568, 0.45);

scene.add(keyLight, fillLight, rimLight, ambientLight);

const cityGroup = new THREE.Group();
scene.add(cityGroup);

const buildingGeo = new THREE.BoxGeometry(1, 1, 1);
const buildingMat = new THREE.MeshStandardMaterial({
  color: 0xe2e8f0,
  roughness: 0.25,
  metalness: 0.75
});

const buildingCount = 1200;
const instancedBuildings = new THREE.InstancedMesh(buildingGeo, buildingMat, buildingCount);
instancedBuildings.castShadow = true;
instancedBuildings.receiveShadow = true;

const dummy = new THREE.Object3D();
const color = new THREE.Color();
let idx = 0;

for (let x = -50; x <= 50; x += 2.5) {
  for (let z = -50; z <= 50; z += 2.5) {
    if (idx >= buildingCount) break;
    if (Math.random() > 0.75) continue;

    const dist = Math.sqrt(x * x + z * z);
    const heightFalloff = Math.max(0.2, 1 - dist / 70);
    const height = (8 + Math.random() * 30 * heightFalloff) * (Math.random() > 0.95 ? 1.6 : 1);
    const width = 1.2 + Math.random() * 1.8;
    const depth = 1.2 + Math.random() * 1.8;

    dummy.position.set(x + (Math.random() - 0.5) * 0.5, height / 2 - 8, z + (Math.random() - 0.5) * 0.5);
    dummy.scale.set(width, height, depth);
    dummy.rotation.y = (Math.random() - 0.5) * 0.08;
    dummy.updateMatrix();
    instancedBuildings.setMatrixAt(idx, dummy.matrix);

    const brightness = 0.82 + Math.random() * 0.18;
    color.setRGB(brightness, brightness, brightness + 0.03);
    instancedBuildings.setColorAt(idx, color);
    idx++;
  }
}

cityGroup.add(instancedBuildings);

const detailGroup = new THREE.Group();
cityGroup.add(detailGroup);

const windowMat = new THREE.MeshStandardMaterial({
  color: 0xffb347,
  emissive: 0xff8c00,
  emissiveIntensity: 0.6,
  roughness: 0.2
});

const glassMat = new THREE.MeshStandardMaterial({
  color: 0x4299e1,
  roughness: 0.05,
  metalness: 0.95,
  transparent: true,
  opacity: 0.75
});

for (let i = 0; i < 35; i++) {
  const h = 20 + Math.random() * 25;
  const w = 2.5 + Math.random() * 2;
  const d = 2.5 + Math.random() * 2;

  const building = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshStandardMaterial({
      color: 0xf7fafc,
      roughness: 0.15,
      metalness: 0.8
    })
  );

  building.position.set(
    (Math.random() - 0.5) * 40,
    h / 2 - 5,
    (Math.random() - 0.5) * 40 + 15
  );
  building.castShadow = true;
  building.receiveShadow = true;

  const floors = Math.floor(h / 3);
  for (let f = 2; f < floors; f++) {
    if (Math.random() > 0.4) {
      const winMesh = new THREE.Mesh(new THREE.PlaneGeometry(w * 0.7, 0.4), windowMat.clone());
      winMesh.position.set(0, -h / 2 + f * 3, d / 2 + 0.02);
      winMesh.material.emissiveIntensity = 0.4 + Math.random() * 0.6;
      building.add(winMesh);

      const winMesh2 = winMesh.clone();
      winMesh2.position.set(0, -h / 2 + f * 3, -d / 2 - 0.02);
      winMesh2.rotation.y = Math.PI;
      building.add(winMesh2);

      const winMesh3 = winMesh.clone();
      winMesh3.position.set(w / 2 + 0.02, -h / 2 + f * 3, 0);
      winMesh3.rotation.y = Math.PI / 2;
      building.add(winMesh3);

      const winMesh4 = winMesh.clone();
      winMesh4.position.set(-w / 2 - 0.02, -h / 2 + f * 3, 0);
      winMesh4.rotation.y = -Math.PI / 2;
      building.add(winMesh4);
    }
  }

  if (Math.random() > 0.6) {
    const antenna = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.1, 4, 8),
      new THREE.MeshStandardMaterial({ color: 0x718096, metalness: 0.9, roughness: 0.2 })
    );
    antenna.position.y = h / 2 + 2;
    building.add(antenna);

    const beacon = new THREE.PointLight(0xff0000, 0.8, 8);
    beacon.position.y = 2.5;
    antenna.add(beacon);
    building.userData.beacon = beacon;
    building.userData.beaconPhase = Math.random() * Math.PI * 2;
  }

  detailGroup.add(building);
}

const vehicleGroup = new THREE.Group();
scene.add(vehicleGroup);

const vehicleGeo = new THREE.CapsuleGeometry(0.12, 0.5, 4, 8);
const vehicleMat = new THREE.MeshStandardMaterial({
  color: 0xcbd5e0,
  metalness: 0.85,
  roughness: 0.15
});

const vehicles = [];
for (let i = 0; i < 40; i++) {
  const vehicle = new THREE.Mesh(vehicleGeo, vehicleMat);
  const laneHeight = 6 + Math.random() * 20;
  const angle = Math.random() * Math.PI * 2;
  const radius = 10 + Math.random() * 35;

  vehicle.position.set(Math.cos(angle) * radius, laneHeight, Math.sin(angle) * radius);
  vehicle.rotation.z = Math.PI / 2;
  vehicle.rotation.y = angle + (Math.random() > 0.5 ? 0 : Math.PI);

  const engine = new THREE.PointLight(0x00ddee, 0.6, 4);
  engine.position.set(-0.4, 0, 0);
  vehicle.add(engine);

  const trail = new THREE.Mesh(
    new THREE.ConeGeometry(0.08, 0.8, 8),
    new THREE.MeshBasicMaterial({ color: 0x00ddee, transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending })
  );
  trail.rotation.z = Math.PI / 2;
  trail.position.set(-0.9, 0, 0);
  vehicle.add(trail);

  vehicle.userData = {
    speed: 0.15 + Math.random() * 0.25,
    direction: new THREE.Vector3(Math.sin(angle + Math.PI / 2), 0, -Math.cos(angle + Math.PI / 2)),
    radius: radius,
    center: new THREE.Vector3(0, laneHeight, 0),
    angle: angle,
    engine: engine,
    trail: trail
  };

  vehicles.push(vehicle);
  vehicleGroup.add(vehicle);
}

const particleCount = 1500;
const particleGeo = new THREE.BufferGeometry();
const particlePos = new Float32Array(particleCount * 3);
const particleVel = [];

for (let i = 0; i < particleCount * 3; i += 3) {
  particlePos[i] = (Math.random() - 0.5) * 120;
  particlePos[i + 1] = Math.random() * 50 - 10;
  particlePos[i + 2] = (Math.random() - 0.5) * 120;
  particleVel.push({
    x: (Math.random() - 0.5) * 0.02,
    y: Math.random() * 0.01,
    z: (Math.random() - 0.5) * 0.02
  });
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePos, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.12,
  transparent: true,
  opacity: 0.4,
  blending: THREE.AdditiveBlending
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 8;
controls.maxDistance = 80;
controls.maxPolarAngle = Math.PI / 2 - 0.05;
controls.target.set(0, 8, 0);

camera.position.set(35, 20, 45);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const dt = clock.getDelta();

  controls.update();

  vehicles.forEach((v, i) => {
    v.userData.angle += v.userData.speed * 0.02;
    v.position.x = Math.cos(v.userData.angle) * v.userData.radius;
    v.position.z = Math.sin(v.userData.angle) * v.userData.radius;
    v.rotation.y = v.userData.angle + Math.PI / 2;

    v.userData.engine.intensity = 0.4 + Math.sin(t * 15 + i) * 0.2;
    v.userData.trail.scale.x = 1 + Math.sin(t * 20 + i) * 0.3;

    v.position.y = v.userData.center.y + Math.sin(t * 2 + i) * 0.5;
  });

  const positions = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    const i3 = i * 3;
    positions[i3] += particleVel[i].x + Math.sin(t * 0.5 + i) * 0.01;
    positions[i3 + 1] += particleVel[i].y;
    positions[i3 + 2] += particleVel[i].z;

    if (positions[i3 + 1] > 40) positions[i3 + 1] = -10;
    if (Math.abs(positions[i3]) > 60) positions[i3] *= -0.5;
    if (Math.abs(positions[i3 + 2]) > 60) positions[i3 + 2] *= -0.5;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  detailGroup.children.forEach((building, i) => {
    if (building.userData.beacon) {
      const pulse = Math.sin(t * 3 + building.userData.beaconPhase) > 0.8 ? 1.2 : 0.2;
      building.userData.beacon.intensity = pulse;
    }
  });

  rimLight.intensity = 0.95 + Math.sin(t * 0.4) * 0.15;

  cityGroup.rotation.y = Math.sin(t * 0.05) * 0.05;

  renderer.render(scene, camera);
}

animate();

